export function classifyChangedFiles(files, { eventName = 'pull_request' } = {}) {
  const plan = emptyPlan();

  if (eventName === 'workflow_dispatch' || files.length === 0) {
    markFull(plan);
  } else {
    for (const file of files) {
      // A full-validation path must not stop deployment-impact discovery for
      // other files in the same commit. Continue classifying so a CI/config
      // change plus real application/docs changes still deploys those targets.
      applyPath(plan, file.replaceAll('\\', '/'));
    }
  }

  if (plan.intermediateIngestion) {
    // Intermediate ingestion changes use the existing merge-gated lanes as one
    // cross-layer acceptance gate. Do not duplicate these suites in a second
    // workflow: force the affected backend/worker/database/browser checks here.
    plan.contracts = true;
    plan.backend = true;
    plan.worker = true;
    plan.database = true;
    plan.e2e = true;
    plan.hygiene = true;
    plan.openapi = true;
    plan.needsNpm = true;
  }

  if (plan.backend) {
    // Any change that can alter backend behaviour is checked against the published
    // OpenAPI contract, as is any change to the contract itself (see above).
    plan.apiContract = true;
  }

  if (plan.frontend || plan.backend || plan.worker || plan.contracts) {
    plan.hygiene = true;
    plan.needsNpm = true;
  }

  // Coverage is a late, non-blocking evidence lane. Production-source and
  // coverage-infrastructure Pull Requests request it after normal quality; manual
  // runs and every merged main commit also record a repository-wide baseline.
  if (eventName === 'workflow_dispatch') {
    plan.coverage = true;
  } else if (eventName === 'push') {
    // Every merged main commit receives a reproducible repository baseline.
    // Main pushes already skip the normal application validation lanes, so this
    // does not duplicate the pre-merge unit suites in hosted CI.
    plan.coverage = true;
  }

  return plan;
}

